187→// updateCommittedFullTranscript replaces the transcript for a specific checkpoint
188→// on /full/current while preserving other checkpoints' transcripts in the tree.
189→func (s *V2GitStore) updateCommittedFullTranscript(ctx context.Context, opts UpdateCommittedOptions, sessionIndex int) error {
190→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
191→	if err := s.ensureRef(refName); err != nil {
192→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
193→	}
194→
195→	parentHash, rootTreeHash, err := s.GetRefState(refName)
196→	if err != nil {
197→		return err
198→	}
199→
200→	basePath := opts.CheckpointID.Path() + "/"
201→	checkpointPath := opts.CheckpointID.Path()
202→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
203→
204→	// Read existing entries and replace transcript for this checkpoint only
205→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
206→	if err != nil {
207→		return err
208→	}
209→
210→	// Clear existing transcript entries at this session path before writing new ones
211→	for key := range entries {
212→		if strings.HasPrefix(key, sessionPath) {
213→			delete(entries, key)
214→		}
215→	}
216→
217→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, opts.Transcript, opts.Agent, sessionPath, entries)
218→	if err != nil {
219→		return err
220→	}
221→
222→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
223→		return err
224→	}
225→
226→	// Splice into existing root tree (preserves other checkpoints' transcripts)
227→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
228→	if err != nil {
229→		return err
230→	}
231→
232→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
233→	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
234→	return s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
235→}
